        "const path = process.env.CAPTURE_PATH;",
        "let calls = [];",
        "try {",
        "  if (existsSync(path)) {",
        "    const parsed = JSON.parse(readFileSync(path, 'utf8'));",
        "    calls = Array.isArray(parsed) ? parsed : [parsed];",
        "  }",
        "} catch {}",
        "calls.push({",
        "  nodeEnv: process.env.NODE_ENV,",
